    engine.sync(next_bar)

    assert len(b.entry_calls) == 2
    rejected, reemit = b.entry_calls
    assert rejected.bar_ts_ms == BAR_TS
    assert reemit.bar_ts_ms == next_bar
    assert reemit.retry_seq == 0
    assert engine.active_intents.keys() == {"L"}


