def __test_run_event_stream_handles_async_gen_not_implemented__():
    """NotImplementedError from the async-gen body is handled like one raised from the outer call.

    A plugin's ``watch_orders`` may raise NotImplementedError from the
    generator body rather than from the outer call — the engine must treat
    both the same way."""
    b = MockBroker()

    def _raise_in_body():
        async def _gen():
            raise NotImplementedError
            # The dead yield only makes _gen an async generator
            # noinspection PyUnreachableCode
            yield  # pragma: no cover — unreachable

        return _gen()

    b.watch_orders = _raise_in_body  # type: ignore[method-assign]
    engine, pos = _mk_engine(b)

    asyncio.run(engine.run_event_stream())


def __test_run_event_stream_reopens_after_an_unexpected_error__(monkeypatch, caplog):
    """A ``watch_orders`` that dies with an unexpected error is reopened, not abandoned.

    The stream is the bot's only PUSH channel for fills; abandoning it after
    one transport-layer surprise left a live bot dispatching orders for hours
    without ever seeing their fills. The reopen is paced by
    ``EVENT_STREAM_RESTART_BACKOFF_S``. A plugin's manual-intervention report
    blocks new entries and is reopened the same way; only cancellation ends
    the task."""
    import logging
    from pynecore.core.broker import sync_engine as se

    b = MockBroker()
    fill = _fill_event("buy", qty=1.0, price=50_000.0,
                       pine_id="L", leg=LegType.ENTRY, xchg_id="x1")
    calls = 0

    def _flaky():
        nonlocal calls
        calls += 1
        attempt = calls

        async def _gen():
            if attempt < 3:
                raise RuntimeError(f"transport surprise {attempt}")
            yield fill

        return _gen()

    slept: list[float] = []

    async def _sleep(delay):
        slept.append(delay)

    monkeypatch.setattr(se.asyncio, "sleep", _sleep)
    b.watch_orders = _flaky  # type: ignore[method-assign]
    engine, _ = _mk_engine(b)

    with caplog.at_level(logging.ERROR, logger=se._log.name):
        asyncio.run(engine.run_event_stream())

    assert calls == 3
    assert slept == list(se.EVENT_STREAM_RESTART_BACKOFF_S[:2])
    assert engine._event_queue.get_nowait() is fill
    assert sum("reopening in" in r.getMessage() for r in caplog.records) == 2

    # A plugin's manual-intervention report from the stream blocks new
    # entries and the stream is reopened like after any other error.
    reports = 0

    def _reporting():
        nonlocal reports
        reports += 1
        attempt = reports

        async def _gen():
            if attempt == 1:
                raise BrokerManualInterventionError("venue says stop")
            yield fill

        return _gen()

    slept.clear()
    b.watch_orders = _reporting  # type: ignore[method-assign]
    engine, _ = _mk_engine(b)
    asyncio.run(engine.run_event_stream())

    assert reports == 2, "the stream was not reopened after the plugin's report"
    assert slept == [se.EVENT_STREAM_RESTART_BACKOFF_S[0]]
    assert engine._event_queue.get_nowait() is fill
    assert engine.quarantine_kind is QuarantineKind.ENTRY_BLOCK
    assert not engine.venue_writes_blocked
    assert any(cause is not None and cause.startswith('intervention:')
               for cause in engine._entry_block_causes)  # type: ignore[attr-defined]


def __test_stop_event_stream_waits_for_the_stream_to_fully_unwind__():
    """``stop_event_stream`` returns only after ``watch_orders`` unwound.

    The runner's teardown closes the broker store and the plugin's HTTP
    client right after stopping the stream — if the stop returned while a
    reconcile pass inside ``watch_orders`` was still executing on the
    broker loop, that pass would hit a closed store / closed socket
    (measured: bybit-spot cycle 108). The generator here blocks in a
    worker thread like a REST read under ``asyncio.to_thread`` and does
    non-instant cleanup in its ``finally``; the join must cover both.
    """
    b = MockBroker()
    in_pass = threading.Event()
    release = threading.Event()
    unwound = threading.Event()

    def _blocking_stream():
        async def _gen():
            try:
                in_pass.set()
                await asyncio.to_thread(release.wait, 5.0)
                yield  # pragma: no cover — cancelled before the first yield
            finally:
                # Cleanup that suspends across loop iterations: a stop that
                # cancels without awaiting the task resolves its own future
                # first, and the join returns before this completes.
                await asyncio.sleep(0.05)
                unwound.set()

        return _gen()

    b.watch_orders = _blocking_stream  # type: ignore[method-assign]
    engine, _pos = _mk_engine(b)

    loop = asyncio.new_event_loop()
    thread = threading.Thread(target=loop.run_forever, daemon=True)
    thread.start()
    try:
        asyncio.run_coroutine_threadsafe(engine.run_event_stream(), loop)
        assert in_pass.wait(5.0)
        # The stop owns both the cancel and the join — a prior cancel
        # request on the concurrent future (the runner also issues one)
        # would schedule the unwinding ahead of the stop on the loop and
        # mask a stop that forgot to await the task.
        join = asyncio.run_coroutine_threadsafe(engine.stop_event_stream(), loop)
        join.result(timeout=5.0)
        assert unwound.is_set()
        assert engine._event_stream_task is None
    finally:
        release.set()
        loop.call_soon_threadsafe(loop.stop)
        thread.join(timeout=5.0)
        loop.close()


