def _l3_stop_gone(b, engine, ctx):
    """Both exits rest a TP, only L2 its SL; L3's SL row is still live in the journal."""
    template = b._mk_order(b.exit_calls[0], 't')
    l2_key, l3_key = f"L2-X{chr(0)}L2", f"L3-X{chr(0)}L3"
    l2_tp, l2_sl = engine.order_mapping[l2_key]
    l3_tp, l3_sl = engine.order_mapping[l3_key]
    b.open_orders = [
        _resting_leg(replace(template, id=l2_tp, side="sell"), qty=0.00999, price=2492.0),
        _resting_leg(replace(template, id=l2_sl, side="sell"), qty=0.00999, stop=2488.5),
        _resting_leg(replace(template, id=l3_tp, side="sell"), qty=0.00999, price=2492.0),
    ]
    b.position = ExchangePosition(
        symbol=SYMBOL, side="long", size=0.01999, entry_price=2489.5,
        unrealized_pnl=0.0, liquidation_price=None, leverage=1.0, margin_mode="cash",
    )
    ctx.upsert_order(
        "sl-L3", symbol=SYMBOL, side="sell", qty=0.00999, state="confirmed",
        intent_key=l3_key, exchange_order_id=l3_sl, from_entry="L3",
        pine_entry_id="L3-X", extras={},
    )
    return l2_key, l3_key


def _stop_coverage_store(tmp_path):
    from pynecore.core.broker.run_identity import RunIdentity
    from pynecore.core.broker.storage import BrokerStore

    store = BrokerStore(tmp_path / "broker.sqlite", plugin_name="testbroker")
    ctx = store.open_run(
        RunIdentity(strategy_id="t025", symbol=SYMBOL, timeframe="60",
                    account_id="testbroker-demo", label=None),
        script_source="src", script_path="t025.py",
    )
    return store, ctx


def __test_stop_rearm_waits_for_the_verdict_on_a_live_stop_row__(tmp_path, caplog):
    """A missing stop whose journal row is still live is not re-armed yet.

    The venue has not said why the stop vanished: its row is live, so the
    disappearance tracker is still checking it, and an external cancel must
    quarantine the run instead of being overridden. Once the verdict closes
    the row (a venue-driven or the bot's own cancel), the absence is
    explained and the regular two-pass re-arm follows.
    """
    store, ctx = _stop_coverage_store(tmp_path)
    with store:
        b = MockBroker(two_leg_exits=True)
        engine, _pos = _spot_like_pyramid(b, store_ctx=ctx)
        l2_key, l3_key = _l3_stop_gone(b, engine, ctx)
        n_cancels = len(b.cancel_calls)
        with caplog.at_level(logging.WARNING, logger="pyne_core_logger"):
            for _ in range(4):
                engine.reconcile()
        assert len(b.cancel_calls) == n_cancels
        waits = [r for r in caplog.records if "waiting for the venue's verdict" in r.getMessage()]
        assert len(waits) == 1 and "sl-L3" in waits[0].getMessage()
        assert l3_key in engine.active_intents

        ctx.close_order("sl-L3")
        engine.reconcile()  # first explained observation
        assert len(b.cancel_calls) == n_cancels
        engine.reconcile()
        cancelled = [(c.intent.pine_id, c.intent.from_entry) for c in b.cancel_calls[n_cancels:]]
        assert cancelled == [("L3-X", "L3")]
        assert l2_key in engine.active_intents
        assert l3_key not in engine.active_intents

        # The script does not re-emit its exit: the next sync re-arms the
        # full bracket from the kept Pine order.
        n_exits = len(b.exit_calls)
        engine.sync(BAR_TS + 10 * 60_000)
        rearmed = b.exit_calls[n_exits:]
        assert [(e.intent.pine_id, e.intent.from_entry) for e in rearmed] == [("L3-X", "L3")]
        assert rearmed[0].intent.sl_price is not None
        assert len(engine.order_mapping[l3_key]) == 2


def __test_stop_rearm_without_a_verdict_is_loud_after_the_ceiling__(tmp_path, caplog):
    """A verdict that never comes re-arms the stop after the ceiling, loudly.

    A lost cancel push with an unreadable order history leaves the row live
    for good; the position must not stay without its stop, so past
    STOP_FATE_VERDICT_CEILING_S the exit is retired for a fresh bracket with
    an ERROR, an audit event and a ProtectionRearmedUnverifiedEvent.
    """
    from pynecore.core.broker.models import ProtectionRearmedUnverifiedEvent
    from pynecore.core.broker.sync_engine import STOP_FATE_VERDICT_CEILING_S

    store, ctx = _stop_coverage_store(tmp_path)
    with store:
        b = MockBroker(two_leg_exits=True)
        engine, _pos = _spot_like_pyramid(b, store_ctx=ctx)
        events: list[BrokerEvent] = []
        engine._broker_event_sink = events.append  # type: ignore[attr-defined]
        l2_key, l3_key = _l3_stop_gone(b, engine, ctx)
        n_cancels = len(b.cancel_calls)
        engine.reconcile()
        assert len(b.cancel_calls) == n_cancels
        engine._stop_fate_pending_since[l3_key] -= STOP_FATE_VERDICT_CEILING_S  # type: ignore[attr-defined]
        with caplog.at_level(logging.ERROR, logger="pyne_core_logger"):
            engine.reconcile()
        cancelled = [(c.intent.pine_id, c.intent.from_entry) for c in b.cancel_calls[n_cancels:]]
        assert cancelled == [("L3-X", "L3")]
        assert l3_key not in engine.active_intents
        assert l2_key in engine.active_intents
        assert [r for r in caplog.records
                if r.levelno == logging.ERROR and "no verdict on the missing stop" in r.getMessage()]
        rearmed = [e for e in events if isinstance(e, ProtectionRearmedUnverifiedEvent)]
        assert len(rearmed) == 1
        assert rearmed[0].intent_key == l3_key and rearmed[0].from_entry == "L3"
        audit = ctx._store._conn.execute(  # type: ignore[attr-defined]
            "SELECT intent_key FROM events WHERE kind = 'stop_coverage_rearm_unverified'",
        ).fetchall()
        assert [row['intent_key'] for row in audit] == [l3_key]

        # A same-bar sync (calc_on_every_tick) re-arms the bracket from the
        # kept Pine order under a fresh client order id: the old bracket's id
        # is spent at the venue.
        spent = b.exit_calls[1]
        assert spent.intent.from_entry == "L3"
        n_exits = len(b.exit_calls)
        engine.sync(spent.bar_ts_ms)
        rearmed = b.exit_calls[n_exits:]
        assert [(e.intent.pine_id, e.intent.from_entry) for e in rearmed] == [("L3-X", "L3")]
        assert rearmed[0].intent.sl_price is not None
        assert (rearmed[0].bar_ts_ms, rearmed[0].retry_seq) != (spent.bar_ts_ms, spent.retry_seq)


def __test_stop_rearm_after_a_delayed_cancel_mints_fresh_ids__(tmp_path):
    """A re-arm cancel that lands only on retry still spends the old ids.

    ``execute_cancel`` returns ``False`` first: the exit stays parked and no
    bracket goes out beside the surviving TP. The next sync's retry lands the
    cancel and re-arms in the same pass; on the original bracket's bar the
    replacement must not reuse its client order id.
    """
    from pynecore.core.broker.sync_engine import STOP_FATE_VERDICT_CEILING_S

    store, ctx = _stop_coverage_store(tmp_path)
    with store:
        b = MockBroker(two_leg_exits=True)
        engine, _pos = _spot_like_pyramid(b, store_ctx=ctx)
        _l2_key, l3_key = _l3_stop_gone(b, engine, ctx)
        engine.reconcile()
        engine._stop_fate_pending_since[l3_key] -= STOP_FATE_VERDICT_CEILING_S  # type: ignore[attr-defined]
        b.false_on_next_cancel = True
        n_cancels = len(b.cancel_calls)
        engine.reconcile()
        assert len(b.cancel_calls) == n_cancels + 1
        assert l3_key in engine._forced_cancel_pending  # type: ignore[attr-defined]
        assert l3_key not in engine.active_intents

        spent = b.exit_calls[1]
        assert spent.intent.from_entry == "L3"
        n_exits = len(b.exit_calls)
        engine.sync(spent.bar_ts_ms)
        assert l3_key not in engine._forced_cancel_pending  # type: ignore[attr-defined]
        rearmed = b.exit_calls[n_exits:]
        assert [(e.intent.pine_id, e.intent.from_entry) for e in rearmed] == [("L3-X", "L3")]
        assert rearmed[0].intent.sl_price is not None
        assert (rearmed[0].bar_ts_ms, rearmed[0].retry_seq) != (spent.bar_ts_ms, spent.retry_seq)
        assert len(engine.order_mapping[l3_key]) == 2


def __test_a_stop_filling_during_the_reconcile_reads_is_not_a_missing_stop__(tmp_path, caplog):
    """An SL fill that lands after the drain does not read as a missing stop.

    Measured live (bybit-inverse cycle 398, L-X): ``reconcile`` drained the
    queue, the position read still showed the parent, then the SL filled
    and the venue cancelled its TP sibling (reduce-only). The open-orders
    read listed neither leg, the plugin had closed the SL's journal row on
    the fill, and the fill waited unbooked in the queue — so the stop pass
    reported the closing parent as unprotected. The next pass books the
    fill and finds nothing to judge. Here the stop of the oldest parent
    fills, the trade the FIFO booking closes.
    """
    store, ctx = _stop_coverage_store(tmp_path)
    with store:
        b = MockBroker(two_leg_exits=True)
        engine, pos = _spot_like_pyramid(b, store_ctx=ctx)
        template = b._mk_order(b.exit_calls[0], 't')
        l2_key, l3_key = f"L2-X{chr(0)}L2", f"L3-X{chr(0)}L3"
        l2_tp, l2_sl = engine.order_mapping[l2_key]
        l3_tp, l3_sl = engine.order_mapping[l3_key]
        l3_legs = [
            _resting_leg(replace(template, id=l3_tp, side="sell"), qty=0.009995, price=2492.0),
            _resting_leg(replace(template, id=l3_sl, side="sell"), qty=0.009995, stop=2488.5),
        ]
        b.position = ExchangePosition(
            symbol=SYMBOL, side="long", size=0.01999, entry_price=2489.5,
            unrealized_pnl=0.0, liquidation_price=None, leverage=1.0, margin_mode="cash",
        )
        sl_fill = replace(
            _fill_event('sell', 0.009995, 2488.5, pine_id="L2-X", leg=LegType.STOP_LOSS,
                        xchg_id=l2_sl, fill_id="sl-l2-fill"),
            from_entry="L2",
        )
        tp_cancel = replace(
            _fill_event('sell', 0.009995, 2492.0, pine_id="L2-X", leg=LegType.TAKE_PROFIT,
                        xchg_id=l2_tp, event_type='cancelled', filled_qty=0.0),
            from_entry="L2", fill_qty=None, fill_price=None,
            cancel_reason='venue_reduce_only',
        )
        ctx.upsert_order(
            "sl-L2", symbol=SYMBOL, side="sell", qty=0.009995, state="confirmed",
            intent_key=l2_key, exchange_order_id=l2_sl, from_entry="L2",
            pine_entry_id="L2-X", extras={},
        )

        async def _sl_fills_between_the_reads(symbol=None):
            # The venue fills the SL after the position read: the plugin closes
            # the leg's journal row on the fill, the push lands in the queue,
            # and the open orders no longer list L2's legs.
            ctx.close_order("sl-L2")
            engine.on_order_event(tp_cancel)
            engine.on_order_event(sl_fill)
            return list(l3_legs)

        b.get_open_orders = _sl_fills_between_the_reads  # type: ignore[method-assign]
        n_cancels = len(b.cancel_calls)
        with caplog.at_level(logging.WARNING, logger="pyne_core_logger"):
            engine.reconcile()
        assert not [r for r in caplog.records if "stop-coverage" in r.getMessage()]
        assert len(b.cancel_calls) == n_cancels

        async def _settled_orders(symbol=None):
            return list(l3_legs)

        b.get_open_orders = _settled_orders  # type: ignore[method-assign]
        b.position = replace(b.position, size=0.009995)
        with caplog.at_level(logging.WARNING, logger="pyne_core_logger"):
            engine.reconcile()
            engine.reconcile()
        assert pos.size == pytest.approx(0.009995)
        assert l2_key not in engine.active_intents
        assert l3_key in engine.active_intents
        assert not [r for r in caplog.records if "stop-coverage" in r.getMessage()]


def __test_a_queued_cancel_of_the_stop_does_not_hide_its_absence__(caplog):
    """Only a queued fill settles a missing stop; a queued cancel push does not.

    The stop vanished and its cancel push landed after the drain: nothing
    of the parent filled, so the parent is still open without its stop and
    the pass reports it as usual.
    """
    b = MockBroker(two_leg_exits=True)
    engine, _pos = _spot_like_pyramid(b)
    template = b._mk_order(b.exit_calls[0], 't')
    l2_key, l3_key = f"L2-X{chr(0)}L2", f"L3-X{chr(0)}L3"
    l2_tp, l2_sl = engine.order_mapping[l2_key]
    l3_tp, l3_sl = engine.order_mapping[l3_key]
    b.position = ExchangePosition(
        symbol=SYMBOL, side="long", size=0.01999, entry_price=2489.5,
        unrealized_pnl=0.0, liquidation_price=None, leverage=1.0, margin_mode="cash",
    )
    sl_cancel = replace(
        _fill_event('sell', 0.009995, 2488.5, pine_id="L2-X", leg=LegType.STOP_LOSS,
                    xchg_id=l2_sl, event_type='cancelled', filled_qty=0.0),
        from_entry="L2", fill_qty=None, fill_price=None,
    )

    async def _stop_cancelled_between_the_reads(symbol=None):
        engine.on_order_event(sl_cancel)
        return [
            _resting_leg(replace(template, id=l2_tp, side="sell"), qty=0.009995, price=2492.0),
            _resting_leg(replace(template, id=l3_tp, side="sell"), qty=0.009995, price=2492.0),
            _resting_leg(replace(template, id=l3_sl, side="sell"), qty=0.009995, stop=2488.5),
        ]

    b.get_open_orders = _stop_cancelled_between_the_reads  # type: ignore[method-assign]
    with caplog.at_level(logging.WARNING, logger="pyne_core_logger"):
        engine.reconcile()
    reports = [r.getMessage() for r in caplog.records if "stop-coverage" in r.getMessage()]
    assert len(reports) == 1 and "re-arming on the next pass" in reports[0]
    assert "L2-X|L2" in reports[0] and "L3-X" not in reports[0]


def _list_resting_stops(b, engine, pos) -> None:
    """Make the mock venue list one resting stop leg per active exit (sized to its parent)."""
    template = b._mk_order(b.exit_calls[0], 't')
    b.open_orders = []
    for key, intent in engine.active_intents.items():
        if not isinstance(intent, ExitIntent):
            continue
        parents = [t for t in pos.open_trades if t.entry_id == intent.from_entry]
        held = sum(abs(t.size) for t in parents)
        reduce_side = "sell" if parents and parents[0].sign > 0 else "buy"
        for leg_id in engine.order_mapping[key]:
            b.open_orders.append(_resting_leg(
                replace(template, id=leg_id, side=reduce_side), qty=held, stop=intent.sl_price))


def _age_shrink_observation(engine, seconds: float) -> None:
    """Pretend the venue has reported the reduced size for ``seconds`` with no fill since."""
    observed = engine._shrink_observed  # type: ignore[attr-defined]
    assert observed is not None
    engine._shrink_observed = (observed[0], observed[1] - seconds)  # type: ignore[attr-defined]
    engine._last_position_fill_monotonic -= seconds  # type: ignore[attr-defined]


def __test_external_partial_reduction_is_adopted_after_the_confirmation_window__():
    """A venue position below the book is booked as a reduction once it is proven external.

    First observation only starts the window; past the grace with no fill and
    nothing in flight the book shrinks through the FIFO, the surviving parent
    keeps its exit, and the next diff amends the bracket to the new size.
    """
    from pynecore.core.broker.sync_engine import EXTERNAL_FLATTEN_CONFIRM_GRACE_S

    b = MockBroker()
    engine, pos = _mk_engine(b)
    _open_long_with_bracket(b, engine, pos)
    key = f"L-X{INTENT_KEY_SEP}L"
    _list_resting_stops(b, engine, pos)
    b.position = ExchangePosition(
        symbol=SYMBOL, side="long", size=0.6, entry_price=50_000.0,
        unrealized_pnl=0.0, liquidation_price=None, leverage=1.0, margin_mode="cross",
    )

    engine.reconcile()
    assert pos.size == 1.0  # observed, not yet adopted
    engine.reconcile()
    assert pos.size == 1.0  # still inside the window

    _age_shrink_observation(engine, EXTERNAL_FLATTEN_CONFIRM_GRACE_S + 1.0)
    n_cancels = len(b.cancel_calls)
    engine.reconcile()
    assert pos.size == pytest.approx(0.6)
    assert [(t.entry_id, round(t.size, 12)) for t in pos.open_trades] == [("L", 0.6)]
    assert pos.closed_trades[-1].size == pytest.approx(0.4)
    assert key in engine.active_intents and "L" in engine.active_intents
    assert len(b.cancel_calls) == n_cancels

    # Pine rebuilds the exit from the shrunk parent: the bracket is amended.
    pos.exit_orders[("L-X", "L")] = _exit_order("L", 0.6, "L-X", stop=49_000.0)
    engine.sync(BAR_TS + 60_000)
    assert b.modify_exit_calls[-1][1].intent.qty == pytest.approx(0.6)
    assert engine.active_intents[key].qty == pytest.approx(0.6)


def __test_external_reduction_waits_the_plugin_declared_fill_report_grace__():
    """A plugin's ``fill_report_grace_s`` replaces the engine default window."""
    b = MockBroker()
    b.fill_report_grace_s = 5.0
    engine, pos = _mk_engine(b)
    _open_long_with_bracket(b, engine, pos)
    _list_resting_stops(b, engine, pos)
    b.position = ExchangePosition(
        symbol=SYMBOL, side="long", size=0.6, entry_price=50_000.0,
        unrealized_pnl=0.0, liquidation_price=None, leverage=1.0, margin_mode="cross",
    )
    engine.reconcile()
    _age_shrink_observation(engine, 4.0)
    engine.reconcile()
    assert pos.size == 1.0  # still inside the declared 5 s
    _age_shrink_observation(engine, 2.0)
    engine.reconcile()
    assert pos.size == pytest.approx(0.6)


def __test_external_reduction_consuming_a_pyramid_parent_retires_it__():
    """An unbound external reduction spending a whole parent cancels its exit and tracking.

    The reduction is bound to no entry, so it settles the bindings oldest
    first, like the trade rows: L1's binding is spent, L2 keeps its own.
    """
    from pynecore.core.broker.sync_engine import EXTERNAL_FLATTEN_CONFIRM_GRACE_S

    b = MockBroker()
    engine, pos = _mk_engine(b)
    for i, pine_id in enumerate(("L1", "L2")):
        pos.entry_orders[pine_id] = _entry_order(pine_id, 1.0)
        pos.exit_orders[(f"{pine_id}-X", pine_id)] = _exit_order(
            pine_id, 1.0, f"{pine_id}-X", stop=49_000.0)
        engine.sync(BAR_TS + i * 60_000)
        engine._route_event(  # type: ignore[attr-defined]
            _fill_event('buy', 1.0, 50_000.0 + i, pine_id=pine_id, xchg_id=f"xchg-{pine_id}"))
    assert pos.size == 2.0
    _list_resting_stops(b, engine, pos)
    b.position = ExchangePosition(
        symbol=SYMBOL, side="long", size=1.0, entry_price=50_000.5,
        unrealized_pnl=0.0, liquidation_price=None, leverage=1.0, margin_mode="cross",
    )
    engine.reconcile()
    _age_shrink_observation(engine, EXTERNAL_FLATTEN_CONFIRM_GRACE_S + 1.0)
    n_cancels = len(b.cancel_calls)
    engine.reconcile()

    assert pos.size == pytest.approx(1.0)
    assert [t.entry_id for t in pos.open_trades] == ["L2"]
    cancelled = [(c.intent.pine_id, c.intent.from_entry) for c in b.cancel_calls[n_cancels:]]
    assert cancelled == [("L1-X", "L1")]
    assert "L1" not in engine.active_intents
    assert f"L1-X{INTENT_KEY_SEP}L1" not in engine.active_intents
    assert ("L1-X", "L1") not in pos.exit_orders
    assert f"L2-X{INTENT_KEY_SEP}L2" in engine.active_intents


def __test_external_reduction_is_not_adopted_while_our_own_close_is_in_flight__(caplog):
    """A dispatched close explains the smaller venue size: no adoption, the fill will.

    Nor a warning: live (ctrader cycle 360, 2026-11-07) a three-leg reversal
    close was netted on the venue while its fills were still streaming in,
    and every reversal logged "confirming the external reduction".
    """
    from pynecore.core.broker.sync_engine import EXTERNAL_FLATTEN_CONFIRM_GRACE_S

    b = MockBroker()
    engine, pos = _mk_engine(b)
    _open_long_with_bracket(b, engine, pos)
    pos.exit_orders[("Close position order", None)] = Order(
        None, -0.4, order_type=_order_type_close, exit_id="Close position order",
    )
    engine.sync(BAR_TS + 60_000)
    assert len(b.close_calls) == 1 and engine.order_mapping[""]
    _list_resting_stops(b, engine, pos)
    b.position = ExchangePosition(
        symbol=SYMBOL, side="long", size=0.6, entry_price=50_000.0,
        unrealized_pnl=0.0, liquidation_price=None, leverage=1.0, margin_mode="cross",
    )
    with caplog.at_level(logging.WARNING):
        engine.reconcile()
        _age_shrink_observation(engine, EXTERNAL_FLATTEN_CONFIRM_GRACE_S + 1.0)
        engine.reconcile()
    assert pos.size == 1.0
    assert not [r for r in caplog.records if "external reduction" in r.getMessage()]

    # The close fill lands and the book agrees with the venue; the observation is dropped.
    engine._route_event(  # type: ignore[attr-defined]
        _fill_event('sell', 0.4, 50_100.0, pine_id="", leg=LegType.CLOSE,
                    xchg_id=engine.order_mapping[""][0], fill_id="c-1"))
    assert pos.size == pytest.approx(0.6)
    engine.reconcile()
    assert engine._shrink_observed is None  # type: ignore[attr-defined]


def __test_a_fill_pushed_during_the_position_read_is_not_an_external_reduction__(caplog):
    """Our own fill queued between the reconcile drain and the read explains the venue.

    Live (bybit-inverse cycle 337, 2026-11-08): an engine-trigger partial TP
    close filled while the periodic reconcile was reading the position. The
    reconcile drains the queue before the read, so the fill was on the venue
    and in the queue but not yet in the book, and the shrink was announced as
    an external reduction. The next drain books it and the views agree.
    """
    class _FillDuringReadBroker(MockBroker):
        engine: OrderSyncEngine | None = None
        pending: OrderEvent | None = None

        async def get_position(self, symbol):
            if self.engine is not None and self.pending is not None:
                self.engine.on_order_event(self.pending)
                self.pending = None
            return await MockBroker.get_position(self, symbol)

    b = _FillDuringReadBroker()
    engine, pos = _mk_engine(b)
    b.engine = engine
    _open_long_with_bracket(b, engine, pos)
    _list_resting_stops(b, engine, pos)
    b.position = ExchangePosition(
        symbol=SYMBOL, side="long", size=0.6, entry_price=50_000.0,
        unrealized_pnl=0.0, liquidation_price=None, leverage=1.0, margin_mode="cross",
    )
    b.pending = _fill_event('sell', 0.4, 50_100.0, pine_id="", leg=LegType.CLOSE,
                            xchg_id="xchg-partial-close", fill_id="pc-1")

    with caplog.at_level(logging.WARNING):
        engine.reconcile()
    assert not [r for r in caplog.records if "external reduction" in r.getMessage()]

    engine.reconcile()
    assert pos.size == pytest.approx(0.6)
    assert engine._shrink_observed is None


def __test_a_dispatched_trigger_close_ahead_of_its_fill_is_no_external_reduction__(caplog):
    """The venue shows our engine-trigger partial close before its fill event arrives.

    Live (capitalcom cycle 439, 2026-11-18, twice): the partial TP close went out,
    the reconcile of the same sync read the venue already reduced, and announced an
    external reduction a moment before the close's own fill was booked. The trigger
    close's mapping is retired at dispatch, so only its dispatch time tells that it
    is our work in flight; once a fill is booked after it, or the fill-report grace
    is over, it no longer is.
    """
    from pynecore.core.broker.sync_engine import EXTERNAL_FLATTEN_CONFIRM_GRACE_S

    b = MockBroker()
    engine, pos = _mk_engine(b)
    _open_long_with_bracket(b, engine, pos)
    _list_resting_stops(b, engine, pos)
    leg = PartialBracketLeg(
        coid="leg-tp", symbol=SYMBOL, pine_id="L-X1", from_entry="L",
        leg_kind=_LEG_KIND_TP_PARTIAL, leg_state=_LEG_STATE_TRIGGERING, side='sell',
        qty=0.4, intent_key=f"L-X1{INTENT_KEY_SEP}L", parent_pine_entry_id="L",
        parent_entry_dispatch_ref="ref-L", intent_partial_qty=0.4,
        trigger_level=50_200.0, oca_group=None, oca_type=None,
    )
    engine._partial_bracket_engine.register_legs([leg])  # type: ignore[attr-defined]
    engine._dispatch_partial_bracket_close(leg)  # type: ignore[attr-defined]
    assert len(b.close_calls) == 1
    b.position = ExchangePosition(
        symbol=SYMBOL, side="long", size=0.6, entry_price=50_000.0,
        unrealized_pnl=0.0, liquidation_price=None, leverage=1.0, margin_mode="cross",
    )

    def notices() -> int:
        return len([r for r in caplog.records
                    if r.levelno == logging.WARNING
                    and "confirming the external reduction" in r.getMessage()])

    with caplog.at_level(logging.WARNING):
        engine.reconcile()
        assert notices() == 0
        # No fill of it within the grace: the shrink is no longer explained by it.
        engine._trigger_close_dispatched_monotonic -= (  # type: ignore[attr-defined]
            EXTERNAL_FLATTEN_CONFIRM_GRACE_S + 1.0)
        engine._last_position_fill_monotonic -= (  # type: ignore[attr-defined]
            EXTERNAL_FLATTEN_CONFIRM_GRACE_S + 1.0)
        engine.reconcile()
    assert notices() == 1


def __test_a_shrink_our_unlisted_protective_leg_may_hold_waits_for_the_grace__(caplog):
    """A venue-fired leg of ours may be the shrink until its fill report is overdue.

    Live (capitalcom cycle 442, 2026-11-19, twice): a pyramid leg's
    position-attached stop and take-profit fired, the position view showed
    the reduction first, and the reconcile announced "confirming the external
    reduction" right before the fill event arrived. A leg the open orders do
    not show resting (a position-attached bracket never does) may hold such
    an unreported fill, so the notice waits for the fill-report grace.
    """
    from pynecore.core.broker.sync_engine import EXTERNAL_FLATTEN_CONFIRM_GRACE_S

    b = MockBroker()
    engine, pos = _mk_engine(b)
    _open_long_with_bracket(b, engine, pos)
    b.open_orders = []
    b.position = ExchangePosition(
        symbol=SYMBOL, side="long", size=0.6, entry_price=50_000.0,
        unrealized_pnl=0.0, liquidation_price=None, leverage=1.0, margin_mode="cross",
    )

    def notices() -> int:
        return len([r for r in caplog.records
                    if r.levelno == logging.WARNING
                    and "confirming the external reduction" in r.getMessage()])

    with caplog.at_level(logging.WARNING):
        engine.reconcile()
        engine.reconcile()
        assert notices() == 0 and pos.size == 1.0
        # Its fill report is overdue: the shrink is now news.
        _age_shrink_observation(engine, EXTERNAL_FLATTEN_CONFIRM_GRACE_S + 1.0)
        engine.reconcile()
    assert notices() == 1


