    engine.sync(BAR_TS + 60_000)
    assert b.entry_calls == [] and b.close_calls == []
    assert "N" not in engine.active_intents

    engine._last_position_fill_monotonic -= EXTERNAL_FLATTEN_CONFIRM_GRACE_S + 1.0  # type: ignore[attr-defined]
