def __test_whole_row_exit_conflicting_with_live_partial_legs_is_skipped_not_fatal__(tmp_path, caplog):
    """A genuine §12 #4 conflict (partial legs of THIS parent under another key, and
    Pine attaches a whole-row exit) is refused — but the run must not end on it: the
    exit is skipped with one ERROR per key and the partial protection stays."""
    from pynecore.core.broker.storage import BrokerStore
    from pynecore.core.broker.idempotency import build_client_order_id, KIND_ENTRY
    from pynecore.core.broker.store_helpers import (
        LEG_KIND_TP_PARTIAL, LEG_KIND_SL_PARTIAL,
    )
    with BrokerStore(tmp_path / "broker.sqlite", plugin_name="testbroker") as store:
        ctx = store.open_run(_restart_identity(), script_source="src", script_path="t.py")
        parent_ref = build_client_order_id(
            run_tag=RUN_TAG, pine_id="L", bar_ts_ms=BAR_TS,
            kind=KIND_ENTRY, retry_seq=0,
        )
        ctx.record_envelope("L", BAR_TS, 0, run_tag=RUN_TAG)
        for leg_kind, level in ((LEG_KIND_TP_PARTIAL, 120.0), (LEG_KIND_SL_PARTIAL, 90.0)):
            _persist_partial_leg(
                ctx, leg_kind=leg_kind, leg_state="pending_entry", trigger_level=level,
                parent_entry_dispatch_ref=parent_ref,
                oca_group="__partial_exit_X_L__", oca_type="cancel",
            )
        b = _software_partial_native_exit_broker()
        pos = BrokerPosition()
        engine = OrderSyncEngine(
            broker=b, position=pos,  # type: ignore[arg-type]
            symbol=SYMBOL, run_tag=RUN_TAG, mintick=1.0, store_ctx=ctx,
        )
        pos.size = 1.0
        pos.reconstruct_parent_trade(entry_id="L", size=1.0, entry_price=100.0)
        pos.exit_orders[("Y", "L")] = _exit_order("L", -1.0, "Y", stop=90.0)

        def conflict_errors() -> list[logging.LogRecord]:
            return [
                rec for rec in caplog.records
                if rec.levelno == logging.ERROR and "whole-row exit" in rec.getMessage()
            ]

        with caplog.at_level(logging.ERROR, logger="pyne_core_logger"):
            engine.sync(BAR_TS)  # must not raise
            assert not engine.quarantined
            assert b.exit_calls == [], "conflicting whole-row exit was dispatched"
            assert "Y\0L" not in engine.active_intents
            assert engine._partial_bracket_engine.has_active_legs_for_intent("X\0L")  # type: ignore[attr-defined]
            assert len(conflict_errors()) == 1
            engine.sync(BAR_TS + 60_000)
            assert not engine.quarantined
            assert b.exit_calls == []
            assert len(conflict_errors()) == 1, "conflict escalated again for the same key"


def __test_stale_pending_partial_legs_are_not_promoted_by_the_new_parent_fill__(tmp_path):
    """Without any whole-row exit in play the danger is promotion itself: the new
    parent's ENTRY fill would arm the previous parent's ``pending_entry`` legs at their
    old levels against the new position. The fill handler must retire them BEFORE the
    promotion step, in the same event."""
    from pynecore.core.broker.storage import BrokerStore
    with BrokerStore(tmp_path / "broker.sqlite", plugin_name="testbroker") as store:
        ctx = store.open_run(_restart_identity(), script_source="src", script_path="t.py")
        _persist_stale_pending_legs(ctx, exit_id="S-X1")
        b = _software_partial_native_exit_broker()
        pos = BrokerPosition()
        engine = OrderSyncEngine(
            broker=b, position=pos,  # type: ignore[arg-type]
            symbol=SYMBOL, run_tag=RUN_TAG, mintick=1.0, store_ctx=ctx,
        )
        pos.entry_orders["L"] = _entry_order("L", 1.0)
        engine.sync(BAR_TS)
        assert len(b.entry_calls) == 1
        assert engine._partial_bracket_engine.has_active_legs_for_intent("S-X1\0L")  # type: ignore[attr-defined]

        engine.on_order_event(_fill_event(
            "buy", qty=1.0, price=50_000.0, pine_id="L", leg=LegType.ENTRY,
        ))
        engine.apply_async_events()

        assert pos.size == 1.0
        assert not engine._partial_bracket_engine.has_active_legs_for_intent("S-X1\0L"), \
            "previous parent's pending legs were promoted onto the new position"  # type: ignore[attr-defined]
        assert not engine._partial_bracket_engine.has_active_partial_bracket(SYMBOL, "L")  # type: ignore[attr-defined]


def __test_consumed_entry_dropped_by_the_script_keeps_its_partial_brackets__(tmp_path):
    """A filled entry the script stops emitting keeps the open position's brackets.

    Measured live on every lane's partial bot (bybit-inverse cycle 337, bar
    320): a second same-direction signal re-places ``strategy.entry("L")``
    while the first fill is still held, the pyramiding limit drops the new
    order, and the consumed entry leaves the intent list. Nothing works on
    the venue any more, yet the cancel diff tore the entry down with its
    envelope and its engine-trigger partial exits; the re-emitted exits then
    read as a previous run's orphans, their live legs were cancelled and the
    long rode on without protection until the next reversal.
    """
    from pynecore.core.broker.storage import BrokerStore
    with BrokerStore(tmp_path / "broker.sqlite", plugin_name="testbroker") as store:
        ctx = store.open_run(_restart_identity(), script_source="src", script_path="t.py")
        b = _software_partial_broker()
        pos = BrokerPosition()
        engine = OrderSyncEngine(
            broker=b, position=pos,
            symbol=SYMBOL, run_tag=RUN_TAG, mintick=1.0, store_ctx=ctx,
        )
        pos.entry_orders["L"] = _entry_order("L", 1.0)
        pos.exit_orders[("X1", "L")] = _exit_order(
            "L", -0.5, "X1", limit=51_000.0, stop=49_000.0,
        )
        pos.exit_orders[("X2", "L")] = _exit_order(
            "L", -0.5, "X2", limit=52_000.0, stop=49_000.0,
        )
        engine.sync(BAR_TS)
        engine.on_order_event(_fill_event(
            "buy", qty=1.0, price=50_000.0, pine_id="L", leg=LegType.ENTRY,
            xchg_id=engine.order_mapping["L"][0],
        ))
        engine.apply_async_events()
        engine.sync(BAR_TS + 60_000)
        legs = engine._partial_bracket_engine
        assert pos.size == 1.0
        assert legs.has_active_legs_for_intent("X1\0L")
        assert legs.has_active_legs_for_intent("X2\0L")

        del pos.entry_orders["L"]
        engine.sync(BAR_TS + 120_000)

        assert legs.has_active_legs_for_intent("X1\0L"), "X1 lost its live legs"
        assert legs.has_active_legs_for_intent("X2\0L"), "X2 lost its live legs"
        assert ("X1", "L") in pos.exit_orders
        assert ("X2", "L") in pos.exit_orders
        assert b.cancel_calls == [], "a consumed entry has nothing to cancel"
        ctx.close()


def __test_venue_reduce_only_cancel_beside_its_sibling_fill_is_info__(caplog):
    """An SL hit that cancels its own reduce-only TP is the bracket working, not a warning.

    Measured live (bybit-inverse cycle 336): every bracket exit logged
    "exit leg ... cancelled by the venue itself (venue_reduce_only)" as a
    WARNING, because the venue tags the OCA fallout of the sibling's fill with
    its reduce-only reason. A lone cancel (no own sibling fill) still warns.
    """
    b = MockBroker()
    engine, pos, tp_id, sl_id = _mk_two_leg_bracket_without_close(b)

    with caplog.at_level(logging.INFO):
        engine.on_order_event(replace(
            _reduce_only_cancel_event(tp_id),
            cancel_reason=CANCEL_REASON_VENUE_REDUCE_ONLY,
        ))
        engine.on_order_event(_sl_leg_fill_event(sl_id))
        engine._drain_events()

    assert not engine._quarantined
    assert pos.size == 0.0
    trimmed = [r for r in caplog.records if "exit leg TP" in r.getMessage()]
    assert [r.levelno for r in trimmed] == [logging.INFO]


def __test_venue_reduce_only_cancel_with_reason_is_trimmed_not_quarantined__(caplog):
    """A cancel the venue attributes to its own reduce-only handling is never
    an external cancel, whatever else sits in the drain batch.

    Measured live (bybit-inverse cycle 53): L3-X's SL fill shrank the shared
    net position, the venue amended L2-X's TP to the residual and cancelled it
    with ``cancelType=CancelByReduceOnly`` — no fill of L2-X's OWN sibling was
    anywhere near, so the batch classifiers could not clear it and the run was
    quarantined for the rest of the cycle. With the plugin passing the reason,
    the lone cancel must trim only the dead TP leg and keep the intent on its
    live SL leg.
    """
    b = MockBroker()
    engine, _, tp_id, sl_id = _mk_two_leg_bracket_without_close(b)

    with caplog.at_level(logging.WARNING):
        engine._route_event(replace(
            _reduce_only_cancel_event(tp_id),
            cancel_reason=CANCEL_REASON_VENUE_REDUCE_ONLY,
        ))

    assert not engine._quarantined
    assert engine.order_mapping.get("TP\0L") == [sl_id]
    assert "TP\0L" in engine.active_intents
    assert [r.levelno for r in caplog.records
            if "cancelled by the venue itself" in r.getMessage()] == [logging.WARNING]


def __test_venue_driven_cancel_of_a_spot_exit_leg_is_trimmed_not_quarantined__():
    """A spot exit leg is a plain sell on the venue, never a reduce-only order.

    The plugin enforces reduce-only in software on spot, so the venue's cancel
    push carries ``reduce_only=False``. The venue's own reason still decides:
    the dead leg is trimmed and its live sibling keeps the intent, exactly as
    the disappearance tracker would retire it.
    """
    b = MockBroker()
    engine, _, tp_id, sl_id = _mk_two_leg_bracket_without_close(b)
    spot_cancel = _reduce_only_cancel_event(tp_id)
    spot_cancel = replace(
        spot_cancel,
        order=replace(spot_cancel.order, reduce_only=False),
        cancel_reason=CANCEL_REASON_VENUE_REJECTED,
    )

    engine._route_event(spot_cancel)

    assert not engine._quarantined
    assert engine.order_mapping.get("TP\0L") == [sl_id]
    assert "TP\0L" in engine.active_intents


def __test_venue_driven_cancel_of_a_resting_entry_retires_it_without_policy__(tmp_path):
    """The venue refusing a resting entry is nobody's intervention.

    A ``CancelByCannotAffordOrderCost``-style cancel arrives on the private
    stream before the tracker ever sees the order missing. It retires the entry
    like a reject, is audited, and leaves the run free to place the entry again.
    """
    from pynecore.core.broker.storage import BrokerStore
    b = MockBroker()  # on_unexpected_cancel == "stop"
    with BrokerStore(tmp_path / "broker.sqlite", plugin_name="testbroker") as store:
        ctx = store.open_run(_restart_identity(), script_source="src", script_path="t.py")
        engine, pos = _mk_engine(b, store_ctx=ctx)
        pos.entry_orders["L"] = _entry_order("L", 1.0, limit=50_000.0)
        engine.sync(BAR_TS)
        assert len(b.entry_calls) == 1
        deal_id = engine.order_mapping["L"][0]

        engine._route_event(replace(
            _cancelled_event(deal_id), cancel_reason=CANCEL_REASON_VENUE_REJECTED,
        ))

        assert engine.quarantined is False
        assert not engine.quarantined
        assert "L" not in engine.order_mapping
        assert "L" not in engine.active_intents
        audited = list(ctx.iter_events_by_kind_since('venue_driven_cancel', 0))
        assert [e['cancel_reason'] for e in audited] == [CANCEL_REASON_VENUE_REJECTED]
        engine.sync(BAR_TS + 60_000)
        assert len(b.entry_calls) == 2, "the strategy's entry is placed again"
        ctx.close()


def __test_a_failed_audit_never_cuts_the_routing_short_and_lands_once__(tmp_path):
    """An audit write that fails is owed: the event's routing completes, the audit lands once."""
    import sqlite3
    from pynecore.core.broker.storage import BrokerStore
    b = MockBroker()
    with BrokerStore(tmp_path / "broker.sqlite", plugin_name="testbroker") as store:
        ctx = store.open_run(_restart_identity(), script_source="src", script_path="t.py")
        engine, pos = _mk_engine(b, store_ctx=ctx)
        pos.entry_orders["L"] = _entry_order("L", 1.0, limit=50_000.0)
        engine.sync(BAR_TS)
        deal_id = engine.order_mapping["L"][0]
        real_log_event = ctx.log_event
        failed: list[str] = []

        def log_event(kind, *args, **fields):
            if kind == 'venue_driven_cancel' and not failed:
                failed.append(kind)
                raise sqlite3.OperationalError("disk I/O error")
            return real_log_event(kind, *args, **fields)

        ctx.log_event = log_event  # type: ignore[method-assign]
        engine._route_event(replace(
            _cancelled_event(deal_id), cancel_reason=CANCEL_REASON_VENUE_REJECTED,
        ))
        assert failed == ['venue_driven_cancel']
        assert "L" not in engine.order_mapping
        assert "L" not in engine.active_intents
        assert list(ctx.iter_events_by_kind_since('venue_driven_cancel', 0)) == []

        engine.sync(BAR_TS + 60_000)
        audited = list(ctx.iter_events_by_kind_since('venue_driven_cancel', 0))
        assert [e['cancel_reason'] for e in audited] == [CANCEL_REASON_VENUE_REJECTED]
        assert len(b.entry_calls) == 2
        assert not engine.quarantined
        ctx.log_event = real_log_event  # type: ignore[method-assign]
        ctx.close()


def __test_venue_driven_cancel_of_a_partially_filled_entry_consumes_it__(tmp_path):
    """The venue cancels the unfilled remainder of a partially filled resting entry.

    The entry is consumed at its filled quantity like a fully filled one: no
    quarantine, the position keeps the 0.4, and neither the remainder nor the
    whole entry is placed again — the sentinel was dropped with the cancel, so
    the next sync re-placed the full 1.0 and the venue held 1.4 where the
    script asked for 1.0. A same-parameter re-issue of the entry while the
    position is open stops at the pyramiding gate.
    """
    from pynecore.core.broker.storage import BrokerStore
    b = MockBroker()  # on_unexpected_cancel == "stop"
    with BrokerStore(tmp_path / "broker.sqlite", plugin_name="testbroker") as store:
        ctx = store.open_run(_restart_identity(), script_source="src", script_path="t.py")
        engine, pos = _mk_engine(b, store_ctx=ctx)
        pos.entry_orders["L"] = _entry_order("L", 1.0, limit=50_000.0)
        engine.sync(BAR_TS)
        deal_id = engine.order_mapping["L"][0]
        engine._route_event(_fill_event(
            "buy", 0.4, 50_000.0, pine_id="L", xchg_id=deal_id,
            event_type='partial', filled_qty=0.4, remaining_qty=0.6,
        ))
        assert pos.size == 0.4

        engine._route_event(replace(
            _cancelled_event(deal_id, filled_qty=0.4),
            cancel_reason=CANCEL_REASON_VENUE_REJECTED,
        ))

        assert engine.quarantined is False
        assert not engine.quarantined
        assert "L" not in engine.order_mapping
        assert engine.active_intents["L"].qty == 0.4
        audited = list(ctx.iter_events_by_kind_since('venue_driven_cancel', 0))
        assert [(e['cancel_reason'], e['filled_qty']) for e in audited] \
            == [(CANCEL_REASON_VENUE_REJECTED, 0.4)]
        engine.sync(BAR_TS + 60_000)
        engine.sync(BAR_TS + 120_000)
        assert len(b.entry_calls) == 1, "the truncated entry was placed again"
        assert pos.size == 0.4

        pos.entry_orders["L"] = _entry_order("L", 1.0, limit=50_000.0)
        engine.sync(BAR_TS + 180_000)
        assert len(b.entry_calls) == 1, "a re-issue passed the pyramiding cap"
        ctx.close()


def __test_venue_driven_cancels_of_an_entry_stop_at_the_retry_cap__():
    """A venue that keeps cancelling the same accepted entry does not get it re-placed forever.

    Each venue-driven cancel retires the entry and the next sync re-places it,
    a dispatch that succeeds and so used to reset the reject memory: under
    ``calc_on_every_tick`` the identical order was re-posted on every tick.
    The cancels count towards the entry retry cap; a re-placement on the bar
    of the cancel mints a fresh client order id, and a re-issue of the entry
    on a later bar is a new signal that is placed again.
    """
    from pynecore.core.broker.idempotency import KIND_ENTRY
    from pynecore.core.broker.sync_engine import _ENTRY_REJECT_RETRY_CAP
    b = MockBroker()
    engine, pos = _mk_engine(b)
    pos.entry_orders["L"] = _entry_order("L", 1.0, limit=50_000.0)
    engine.sync(BAR_TS)
    for _ in range(8):
        mapped = engine.order_mapping.get("L")
        if mapped is None:
            break
        engine._route_event(replace(
            _cancelled_event(mapped[0]), cancel_reason=CANCEL_REASON_VENUE_REJECTED,
        ))
        engine.sync(BAR_TS)
    assert len(b.entry_calls) == _ENTRY_REJECT_RETRY_CAP
    coids = [envelope.client_order_id(KIND_ENTRY) for envelope in b.entry_calls]
    assert len(set(coids)) == len(coids), "a same-bar re-placement reused a spent id"
    assert engine.quarantined is False
    engine.sync(BAR_TS)
    assert len(b.entry_calls) == _ENTRY_REJECT_RETRY_CAP

    pos.entry_orders["L"] = _entry_order("L", 1.0, limit=50_000.0)
    engine.sync(BAR_TS + 60_000)
    assert len(b.entry_calls) == _ENTRY_REJECT_RETRY_CAP + 1


def __test_restart_partial_bracket_of_a_rotated_bot_is_adopted_not_cancelled__(tmp_path):
    """The legs of a previous bot with another run_tag are adopted, not torn down.

    Measured live (capitalcom cycle 113): the trailing bot replayed the
    partial bot's ``L-X2|L`` legs (same logical run_id, different script,
    different tag), rebuilt the parent ref under its OWN tag, saw a mismatch
    on every leg, cancelled them and re-armed a fresh bracket against a
    parent ref no order row carries — the native fail-safe then degraded on
    136 refused PUTs in one bar. With the anchor carrying its tag the refs
    match and the adoption branch pins the intent on the live legs.
    """
    from pynecore.core.broker.storage import BrokerStore
    from pynecore.core.broker.idempotency import build_client_order_id, KIND_ENTRY
    from pynecore.core.broker.store_helpers import (
        LEG_KIND_TP_PARTIAL, LEG_KIND_SL_PARTIAL,
    )
    with BrokerStore(tmp_path / "broker.sqlite", plugin_name="testbroker") as store:
        ctx = store.open_run(_restart_identity(), script_source="src", script_path="t.py")
        parent_ref = build_client_order_id(
            run_tag="prev", pine_id="L", bar_ts_ms=BAR_TS,
            kind=KIND_ENTRY, retry_seq=0,
        )
        ctx.record_envelope("L", BAR_TS, 0, run_tag="prev")
        _persist_partial_leg(ctx, leg_kind=LEG_KIND_TP_PARTIAL, trigger_level=120.0,
                             parent_entry_dispatch_ref=parent_ref,
                             oca_group="__partial_exit_X_L__", oca_type="cancel")
        _persist_partial_leg(ctx, leg_kind=LEG_KIND_SL_PARTIAL, trigger_level=90.0,
                             parent_entry_dispatch_ref=parent_ref,
                             oca_group="__partial_exit_X_L__", oca_type="cancel")
        pos = BrokerPosition()
        engine = OrderSyncEngine(
            broker=_software_partial_broker(), position=pos,  # type: ignore[arg-type]
            symbol=SYMBOL, run_tag=RUN_TAG, mintick=1.0, store_ctx=ctx,
        )
        assert RUN_TAG != "prev"
        assert engine._resolve_parent_opening_ref("L") == parent_ref  # type: ignore[attr-defined]
        pos.size = 1.0
        pos.reconstruct_parent_trade(entry_id="L", size=1.0, entry_price=100.0)
        engine.sync(BAR_TS)
        assert "X\0L" in engine.active_intents
        legs = [
            leg for leg in engine._partial_bracket_engine.iter_legs()  # type: ignore[attr-defined]
            if leg.intent_key == "X\0L"
        ]
        assert len(legs) == 2
        assert all(leg.parent_entry_dispatch_ref == parent_ref for leg in legs), \
            "the replayed legs were replaced by a fresh bracket"


def __test_read_outage_warnings_are_throttled_across_tick_syncs__(caplog):
    """
    ``calc_on_every_tick`` syncs on every market update, and a feed reconnect
    can replay a burst of ticks in well under a second: during a read outage
    every one of those syncs used to write the same WARNING lines. The outage
    is reported once per ``READ_OUTAGE_WARN_INTERVAL_S`` per unconfirmed
    stretch — the first failure immediately — and the throttle resets once a
    read confirms the view, so the next outage is again reported at once.
    """
    class _ReadsDownBroker(MockBroker):
        down: bool = False

        async def get_open_orders(self, symbol=None):
            if self.down:
                raise ExchangeConnectionError("not connected")
            return await MockBroker.get_open_orders(self, symbol)

        async def get_position(self, symbol):
            if self.down:
                raise ExchangeConnectionError("not connected")
            return await MockBroker.get_position(self, symbol)

    b = _ReadsDownBroker()
    engine, _ = _mk_engine(b)
    engine._reconcile_every = 1
    engine.sync(BAR_TS)

    def outage_warnings() -> list[logging.LogRecord]:
        return [
            rec for rec in caplog.records
            if rec.levelno == logging.WARNING and "not connected" in rec.getMessage()
        ]

    with caplog.at_level(logging.WARNING, logger="pyne_core_logger"):
        b.down = True
        # A burst of tick syncs inside one outage: reported exactly once.
        for i in range(6):
            engine.sync(BAR_TS + 1_000 * i)
        assert not engine.quarantined
        assert len(outage_warnings()) == 1, "burst syncs re-reported the same outage"
        assert not engine._read_view_confirmed

        # Past the interval the outage is reported again, with the view age.
        engine._read_outage_warned_at -= READ_OUTAGE_WARN_INTERVAL_S + 1.0
        engine._reads_unconfirmed_since -= 5.0
        engine.sync(BAR_TS + 60_000)
        assert len(outage_warnings()) == 2
        assert "unconfirmed for 5s" in outage_warnings()[-1].getMessage()
        assert "deferred" in outage_warnings()[-1].getMessage()

        # Reads recover: the throttle resets, so a fresh outage is reported
        # immediately rather than waiting out the previous stretch's interval.
        b.down = False
        engine.sync(BAR_TS + 120_000)
        assert engine._read_view_confirmed
        b.down = True
        engine.sync(BAR_TS + 121_000)
        assert len(outage_warnings()) == 3


def _start_test_loop() -> tuple[asyncio.AbstractEventLoop, asyncio.Event]:
    """Start a broker loop on a daemon thread; ``release`` frees stalled coroutines."""
    loop = asyncio.new_event_loop()
    thread = threading.Thread(target=loop.run_forever, daemon=True, name="test-loop")
    thread.start()
    started = threading.Event()
    loop.call_soon_threadsafe(started.set)
    assert started.wait(timeout=5.0), "loop failed to start"
    return loop, asyncio.Event()


def _stop_test_loop(loop: asyncio.AbstractEventLoop, release: asyncio.Event) -> None:
    """Release every stalled coroutine, let it finish, then stop the loop."""
    async def _finish() -> None:
        release.set()
        await asyncio.sleep(0)
        await asyncio.sleep(0)

    asyncio.run_coroutine_threadsafe(_finish(), loop).result(timeout=5.0)
    loop.call_soon_threadsafe(loop.stop)


def __test_recovery_bridge_timeout_surfaces_unknown_disposition__():
    """An expired bridge wait on a one-way recovery step is an unknown disposition, not a crash."""
    loop, release = _start_test_loop()
    try:
        b = MockBroker()
        engine = OrderSyncEngine(
            broker=b,  # type: ignore[arg-type]
            position=BrokerPosition(),
            symbol=SYMBOL,
            run_tag=RUN_TAG,
            event_loop=loop,
            execute_timeout=0.1,
        )
        with pytest.raises(OrderDispositionUnknownError) as excinfo:
            engine._run_async_recovery(release.wait(), client_order_id="coid-clear")
        assert excinfo.value.client_order_id == "coid-clear"
        assert isinstance(excinfo.value.cause, TimeoutError)
    finally:
        _stop_test_loop(loop, release)


def __test_hedging_exit_cancel_bridge_timeout_does_not_crash__(tmp_path):
    """A stalled per-exit bracket clear retires the exit instead of killing the run.

    Measured live 2026-10-04 (bybit chaos cycle 228): a REST stall made the
    one-way ``run_exit_bracket_clear`` outrun the dispatch bridge inside
    ``_dispatch_cancel`` and the raw ``TimeoutError`` escaped ``_broker_sync``.
    """
    from pynecore.core.broker.storage import BrokerStore

    loop, release = _start_test_loop()
    try:
        with BrokerStore(tmp_path / "broker.sqlite", plugin_name="testbroker") as store:
            ctx = store.open_run(_restart_identity(), script_source="src", script_path="t.py")
            b = MockBroker()
            b.position_port = b
            b.raw_legs = [_pleg("1", "buy", 2.0)]
            engine = OrderSyncEngine(
                broker=b,  # type: ignore[arg-type]
                position=BrokerPosition(),
                symbol=SYMBOL,
                run_tag=RUN_TAG,
                event_loop=loop,
                execute_timeout=0.1,
                store_ctx=ctx,
            )
            ex = ExitIntent(pine_id="X", from_entry="L", symbol=SYMBOL, side="sell",
                            qty=2.0, tp_price=120.0, sl_price=90.0)
            engine._dispatch_new(ex)
            assert set(engine.order_mapping[ex.intent_key]) == {"bracket:1"}

            stalled = threading.Event()

            async def _stalled_amend(symbol, leg_id, *, side, tp_price, sl_price,
                                     trail_offset, qty, coid):
                stalled.set()
                await release.wait()

            b.amend_bracket = _stalled_amend
            engine._dispatch_cancel(ex)
            assert stalled.is_set(), "the bracket clear never reached the port"
            # Unknown disposition on a whole-row exit: eager retire, no halt.
            assert ex.intent_key not in engine.order_mapping
            assert engine._cancel_disposition_pending == {}
    finally:
        _stop_test_loop(loop, release)


def __test_a_stalled_retirement_cannot_overwrite_a_newer_stop__(tmp_path):
    """A retirement the bridge gave up on holds the leg until it ends, so it cannot land last.

    The stalled clear keeps running on the broker loop after the bridge wait
    expired. A fresh attach of the exit sent meanwhile would reach the venue
    first and be wiped when the clear finally lands, leaving the position
    without its stop.
    """
    from pynecore.core.broker.storage import BrokerStore

    loop, release = _start_test_loop()
    try:
        with BrokerStore(tmp_path / "broker.sqlite", plugin_name="testbroker") as store:
            ctx = store.open_run(_restart_identity(), script_source="src", script_path="t.py")
            b = MockBroker()
            b.position_port = b
            b.raw_legs = [_pleg("1", "buy", 2.0)]
            engine = OrderSyncEngine(
                broker=b,  # type: ignore[arg-type]
                position=BrokerPosition(),
                symbol=SYMBOL,
                run_tag=RUN_TAG,
                event_loop=loop,
                execute_timeout=0.1,
                store_ctx=ctx,
            )
            ex = ExitIntent(pine_id="X", from_entry="L", symbol=SYMBOL, side="sell",
                            qty=2.0, tp_price=120.0, sl_price=90.0)
            engine._dispatch_new(ex)

            stalled = threading.Event()
            venue_writes: list[tuple[float | None, float | None]] = []
            healthy_amend = b.amend_bracket

            async def _stalled_amend(symbol, leg_id, *, side, tp_price, sl_price,
                                     trail_offset, qty, coid):
                stalled.set()
                await release.wait()
                venue_writes.append((tp_price, sl_price))

            async def _recording_amend(symbol, leg_id, *, side, tp_price, sl_price,
                                       trail_offset, qty, coid):
                venue_writes.append((tp_price, sl_price))
                await healthy_amend(symbol, leg_id, side=side, tp_price=tp_price,
                                    sl_price=sl_price, trail_offset=trail_offset,
                                    qty=qty, coid=coid)

            b.amend_bracket = _stalled_amend
            engine._dispatch_cancel(ex)
            assert stalled.is_set()
            # The script places the exit again with a new stop while the clear
            # is still in flight: it is parked, nothing reaches the venue.
            b.amend_bracket = _recording_amend
            newer = ExitIntent(pine_id="X", from_entry="L", symbol=SYMBOL, side="sell",
                               qty=2.0, tp_price=120.0, sl_price=95.0)
            engine._dispatch_new(newer)
            engine._active_intents[newer.intent_key] = newer
            assert venue_writes == []

            # The clear lands late. The settle pass then brings the leg to the
            # exit's levels: the newer stop is the LAST write on the venue.
            emulator = engine._one_way_emulator
            asyncio.run_coroutine_threadsafe(
                _release_and_let_finish(release, emulator), loop).result(timeout=5.0)
            engine._settle_one_way_leg_writes(b)
            assert venue_writes == [(None, None), (120.0, 95.0)]
            assert engine.pending_verification == {}
    finally:
        _stop_test_loop(loop, release)


async def _release_and_let_finish(release: asyncio.Event, emulator) -> None:
    """Free the stalled port call and yield until its write is settled by its own return."""
    release.set()
    for _ in range(100):
        if not emulator._unsettled_writes:
            return
        await asyncio.sleep(0)


# --- External-intervention quarantine -------------------------------------------


def _venue_write_counts(b: MockBroker) -> tuple[int, ...]:
    return (
        len(b.entry_calls), len(b.exit_calls), len(b.close_calls),
        len(b.cancel_calls), len(b.modify_entry_calls), len(b.modify_exit_calls),
    )


def __test_an_operator_cancel_quarantines_and_the_bot_never_rebuilds_the_leg__():
    """An operator deleting the bot's TP leaves the venue exactly as they left it.

    The unexpected-cancel teardown drops the exit's tracking but Pine still
    declares the exit; with an entry-only quarantine the next sync re-dispatched
    the deleted leg. The operator's change must stand: no write of any kind.
    """
    b = MockBroker()
    engine, pos, tp_id = _mk_bracket_with_inflight_close(b)
    engine._active_intents.pop("L", None)
    before = _venue_write_counts(b)

    engine._route_event(_reduce_only_cancel_event(tp_id))

    assert engine.quarantine_kind is QuarantineKind.EXTERNAL_INTERVENTION
    assert engine.venue_writes_blocked
    assert ("TP", "L") in pos.exit_orders, "Pine still declares the deleted exit"
    pos.entry_orders["L2"] = _entry_order("L2", 1.0)
    reads_before = b.get_position_calls
    for i in range(3):
        engine.sync(BAR_TS + (i + 1) * 60_000)
    engine.reconcile()
    assert _venue_write_counts(b) == before
    assert b.get_position_calls == reads_before, "no reconcile repair under the latch"


def __test_an_event_drained_under_the_latch_is_booked_without_its_follow_up_write__():
    """A fill that arrives during the quarantine is booked; nothing is dispatched for it."""
    b = MockBroker()
    engine, pos = _mk_engine(b)
    pos.entry_orders["L"] = _entry_order("L", 1.0)
    pos.exit_orders[("TP", "L")] = _exit_order(
        "L", -1.0, "TP", limit=60_000.0, stop=45_000.0,
    )
    engine.sync(BAR_TS)
    before = _venue_write_counts(b)
    engine.record_quarantine("operator edit", kind=QuarantineKind.EXTERNAL_INTERVENTION)

    engine.on_order_event(_fill_event("buy", 1.0, 50_000.0, pine_id="L"))
    engine.sync(BAR_TS + 60_000)

    assert pos.size == 1.0
    assert _venue_write_counts(b) == before


def __test_a_cancel_tentative_oca_entry_filling_under_the_latch_is_booked__():
    """The OCA sibling cancel the late fill triggers is refused, the fill is still booked.

    The cancel-tentative restore runs the OCA cascade BEFORE ``record_fill``;
    a refused sibling cancel there must not drop the fill on the floor.
    """
